"""Persistent shared JSON cache for public demonstration profiles."""
import json
import os
import time
from app.config import CACHE_PATH, CACHE_TTL


def get_or_load(key, loader, now=None):
    """Load from shared cache for a key while still active, otherwise reload it."""
    if now is None:
        now = time.time()

    try:
        with open(CACHE_PATH, 'r') as f:
            cache_data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return loader()

    entry = cache_data.get(key)
    if entry is None:
        return loader()

    stored_at = entry.get('stored_at')
    if stored_at is None or (now - stored_at) >= CACHE_TTL:
        return loader()

    return entry.get('value')
